import pathlib

def image_files(root):
    def is_image(path):
        return path.suffix.lower() in {".png", ".jpg"}

    def exclude_dirs(path):
        return not path.name.lower().endswith(".png") and not path.name.lower().endswith(".jpg")

    return sorted(pathlib.Path(root).rglob("*"), key=lambda p: p.name.lower()) if exclude_dirs(pathlib.Path(root)) else []

import json

def decode_record(payload):
    try:
        decoded_payload = payload.decode('utf-8')
        data = json.loads(decoded_payload)
        if isinstance(data, dict) and 'record' in data:
            return data['record']
        else:
            raise ValueError("Invalid JSON or missing record field")
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON")
    except UnicodeDecodeError:
        raise ValueError("Bad encoding")

