def stream_window(stream, start, stop):
    for i, item in enumerate(stream):
        if start <= i < stop:
            yield i, item

import collections

def group_updates(updates):
    updates_dict = collections.defaultdict(list)
    for key, value in updates:
        updates_dict[key].append(value)
    return sorted(updates_dict.items())

def merge_config(base, patch):
    if base is None:
        return patch
    elif patch is None:
        return base
    elif isinstance(base, dict) and isinstance(patch, dict):
        merged = {}
        for key in base.keys():
            merged[key] = merge_config(base[key], patch.get(key))
        for key in patch.keys():
            if key not in base:
                merged[key] = patch[key]
        return merged
    else:
        return patch

import os
from pathlib import Path
from datetime import datetime

def report_paths(root):
    paths = []
    for file in os.listdir(root):
        if file.startswith("report-") and file.endswith(".csv"):
            date_str = file[7:-4]
            try:
                date = datetime.strptime(date_str, "%Y-%m-%d")
                paths.append((date, Path(os.path.join(root, file))))
            except ValueError:
                continue
    paths.sort(key=lambda x: x[0])
    return paths

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("Invalid input values")
    start = page * size
    stop = min(start + size, total)
    return start, stop

import collections

def summarize_jobs(jobs):
    summary = collections.defaultdict(lambda: (0, 0))
    for job in jobs:
        summary[job.status] = (summary[job.status][0] + 1, summary[job.status][1] + job.size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

import time
from typing import Callable, Optional, Union

def retry_read(read: Callable[[], Union[None, Exception]], attempts: int) -> Union[None, Exception]:
    if attempts < 1:
        raise ValueError("attempts must be at least one")

    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            if attempt < attempts - 1:
                time.sleep(1)  # Optional: Sleep between retries
            else:
                raise ValueError("All attempts timed out")

