import csv

def render_row(fields, record, missing="-"):
    def escape(s):
        return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n")

    def render_field(field):
        if field is None:
            return missing
        elif field is False:
            return "False"
        elif field is True:
            return "True"
        else:
            return escape(str(field))

    return "\t".join(render_field(field) for field in fields)
